    const method=request.method.toUpperCase();
    if(method==="GET" && url.pathname==="/api/admin/orders") return Response.json({ok:true,...await store.adminOrdersList({search:url.searchParams.get("search")||"",status:url.searchParams.get("status")||"",paymentStatus:url.searchParams.get("paymentStatus")||"",fulfillmentMode:url.searchParams.get("fulfillmentMode")||"",dateFrom:url.searchParams.get("dateFrom")||"",dateTo:url.searchParams.get("dateTo")||"",sort:url.searchParams.get("sort")||"date",direction:url.searchParams.get("direction")||"desc",page:Number(url.searchParams.get("page")||1),pageSize:Number(url.searchParams.get("pageSize")||20)}) as any});
