    const noteMatch=url.pathname.match(/^\/api\/admin\/orders\/([^/]+)\/notes$/);
    if(method==="POST" && noteMatch){const body=await request.json() as any; return Response.json({ok:true,order:await store.adminOrderAddNote(identity.id,decodeURIComponent(noteMatch[1]),String(body.note||""))});}
