async function adminDashboardApi(request: Request, env: Env): Promise<Response | null> {
  const url=new URL(request.url); if(url.pathname!=="/api/admin/dashboard") return null;
  const claims=await getAdminSessionClaims(request,env);
  const store=env.ITEMS.get(env.ITEMS.idFromName("default"));
  const identity=claims?await store.adminIdentity(claims.userId):null;
  if(!identity) return Response.json({ok:false,error:"Unauthorized"},{status:401});
  if(request.method!=="GET") {
    if(!await store.adminPermission(identity.id,"admin.dashboard","modify")) return Response.json({ok:false,error:"Permission denied."},{status:403});
    return Response.json({ok:false,error:"Method not allowed"},{status:405});
  }
  if(!await store.adminPermission(identity.id,"admin.dashboard","access")) return Response.json({ok:false,error:"Permission denied."},{status:403});
  const navDefs=[["orders","admin.orders"],["manualReview","admin.manual_review"],["production","admin.production"],["products","admin.products"],["printify","admin.products.printify"],["customers","admin.customers"],["designers","admin.designers"],["payouts","admin.payouts"],["reports","admin.reports"],["settings","admin.settings"],["audit","admin.audit_log"]] as const;
  const access:Record<string,boolean>={};
  for(const [key,resource] of navDefs) access[key]=await store.adminPermission(identity.id,resource,"access");
  return Response.json({ok:true,summary:await store.adminDashboardSummary(),access});
}

