async function studioApi(request: Request, env: Env): Promise<Response | null> { const url = new URL(request.url); if (!url.pathname.startsWith("/api/studio/")) return null; const method = request.method.toUpperCase(); const store = env.ITEMS.get(env.ITEMS.idFromName("default")); if (url.pathname === "/api/studio/navigation") { if (method === "GET") return Response.json({ ok: true, source: "dtf-studio-database", navigation: await store.navigationItems() }); if (method === "PUT") { try { const payload = await request.json() as { navigation?: unknown }; if (!Array.isArray(payload.navigation)) return Response.json({ ok: false, error: "navigation must be an array" }, { status: 400 }); return Response.json({ ok: true, source: "dtf-studio-database", navigation: await store.saveNavigationItems(payload.navigation as Parameters<ItemStore["saveNavigationItems"]>[0]) }); } catch (error) { return Response.json({ ok: false, error: error instanceof Error ? error.message : "Invalid navigation payload" }, { status: 400 }); } } return new Response("Method not allowed", { status: 405 }); } if (method !== "GET") return new Response("Method not allowed", { status: 405 }); if (url.pathname === "/api/studio/designs") return Response.json({ ok: true, source: "dtf-studio-database", designs: await store.designs() }); if (url.pathname === "/api/studio/products") return Response.json({ ok: true, source: "dtf-studio-database", pricingCurrency: "JOD", products: await store.products() }); if (url.pathname === "/api/studio/categories") return Response.json({ ok: true, source: "dtf-studio-database", categories: await store.categories() }); if (url.pathname === "/api/studio/health") return Response.json({ ok: true, health: await store.health() }); return new Response("Not found", { status: 404 }); }
